import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as DataTable from "../../ui/data-table";

// MODEL
export const Model = S.Struct({ openPaymentId: S.String });
export type Model = typeof Model.Type;
// MESSAGE
export const ClickedOpenActions = m("ClickedOpenActions", {
  paymentId: S.String,
});
export const ClickedCopyPaymentId = m("ClickedCopyPaymentId", {
  paymentId: S.String,
});
export const ClickedViewCustomer = m("ClickedViewCustomer", {
  paymentId: S.String,
});
export const ClickedViewPaymentDetails = m("ClickedViewPaymentDetails", {
  paymentId: S.String,
});
export const Message = S.Union([
  ClickedOpenActions,
  ClickedCopyPaymentId,
  ClickedViewCustomer,
  ClickedViewPaymentDetails,
]);
export type Message = typeof Message.Type;
// INIT
export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ openPaymentId: "" }, []];
// UPDATE
export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedOpenActions: ({ paymentId }) => [
        evo(model, {
          openPaymentId: (openPaymentId) =>
            openPaymentId === paymentId ? "" : paymentId,
        }),
        [],
      ],
      ClickedCopyPaymentId: () => [evo(model, { openPaymentId: () => "" }), []],
      ClickedViewCustomer: () => [evo(model, { openPaymentId: () => "" }), []],
      ClickedViewPaymentDetails: () => [
        evo(model, { openPaymentId: () => "" }),
        [],
      ],
    })
  );
// VIEW
export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();
  return h.div(
    [h.Class("space-y-4")],
    [
      DataTable.paymentsTableView<Message>({
        payments: DataTable.payments.slice(0, 5),
        actionView: (payment) =>
          h.div(
            [h.Class("relative inline-flex flex-col items-end gap-2")],
            [
              h.button(
                [
                  h.Type("button"),
                  h.AriaLabel(`Open menu for ${payment.email}`),
                  h.Attribute("aria-haspopup", "menu"),
                  h.Attribute(
                    "aria-expanded",
                    model.openPaymentId === payment.id ? "true" : "false"
                  ),
                  h.Class(DataTable.dataTableButtonClassName),
                  h.OnClick(ClickedOpenActions({ paymentId: payment.id })),
                ],
                ["Open menu"]
              ),
              model.openPaymentId === payment.id
                ? h.div(
                    [
                      h.Attribute("role", "menu"),
                      h.Class(`${DataTable.dataTableMenuClassName} min-w-40`),
                    ],
                    [
                      h.button(
                        [
                          h.Type("button"),
                          h.Attribute("role", "menuitem"),
                          h.Class(DataTable.dataTableMenuItemClassName),
                          h.OnClick(
                            ClickedCopyPaymentId({ paymentId: payment.id })
                          ),
                        ],
                        ["Copy payment ID"]
                      ),
                      h.button(
                        [
                          h.Type("button"),
                          h.Attribute("role", "menuitem"),
                          h.Class(DataTable.dataTableMenuItemClassName),
                          h.OnClick(
                            ClickedViewCustomer({ paymentId: payment.id })
                          ),
                        ],
                        ["View customer"]
                      ),
                      h.button(
                        [
                          h.Type("button"),
                          h.Attribute("role", "menuitem"),
                          h.Class(DataTable.dataTableMenuItemClassName),
                          h.OnClick(
                            ClickedViewPaymentDetails({
                              paymentId: payment.id,
                            })
                          ),
                        ],
                        ["View payment details"]
                      ),
                    ]
                  )
                : h.empty,
            ]
          ),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("data-table-row-actions example", () => {
  test("renders the shadcn Data Table Row Actions example", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.click(
        Scene.role("button", { name: "Open menu for m@example.com" })
      ),
      Scene.expect(
        Scene.role("menuitem", { name: "Copy payment ID" })
      ).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "View customer" })).toExist(),
      Scene.expect(
        Scene.role("menuitem", { name: "View payment details" })
      ).toExist()
    );
  });
});
